from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if seen[i][j] or g[i][j]==0: continue
            c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; q.append((ny,nx))
            ys=[a for a,_ in cells]; xs=[b for _,b in cells]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            rect = len(cells)==(y1-y0+1)*(x1-x0+1)
            out.append((c,y0,y1,x0,x1,rect,len(cells)))
    return out
