def solid_rect_mask(grid, min_h=3, min_w=3):
    """Boolean mask of cells lying inside a solid monochromatic rectangle at least min_h x min_w."""
    h, w = len(grid), len(grid[0])
    mask = [[False] * w for _ in range(h)]
    for a in range(h):
        for b in range(w):
            c = grid[a][b]
            for hh in range(min_h, h - a + 1):
                if any(grid[a + t][b] != c for t in range(hh)):
                    break
                for ww in range(min_w, w - b + 1):
                    if all(grid[a + t][b + u] == c for t in range(hh) for u in range(ww)):
                        for t in range(hh):
                            for u in range(ww):
                                mask[a + t][b + u] = True
    return mask

def paint_mask(grid, mask, color):
    """Cells where mask is True become color."""
    return [[color if m else v for v, m in zip(row, mr)] for row, mr in zip(grid, mask)]
''')
